 const index=id=>['lead_vivi','lead_muma','lead_monv'].indexOf(id);
 const role=(id,rows)=>rows[index(id)];
 function ack(id,key,value){const v=value;
  if(key==='name')return role(id,[
   [`${v}，好，我以后就这么叫你啦。`,`那就叫你${v}。先说好，不许下次又装不认识。`,`好，${v}，这下不用一直你呀你呀地叫了。`,`收到，${v}。这个称呼我先占个位。`,`好嘛，${v}，今天算正式认识啦。`,`记住啦，${v}。你这名字还挺好接话。`,`那我叫你${v}，你可得答应一声。`],
   [`${v}呀，那就这么叫。`,`好，${v}。这下又熟悉一点了。`,`我记着啦，${v}，下次不用重新报到。`,`嗯，${v}，慢慢聊就认识了。`,`那以后叫你${v}，不许突然装没听见。`,`好，${v}，这个称呼我收好了。`,`知道啦，${v}。不用每次都这么正式。`],
   [`${v}。行，这回总算不用猜名字了。`,`好，${v}，点名了可得答到。`,`收到，${v}。不用再发身份证明了。`,`那就${v}，备注先这么放着。`,`记住了，${v}，下次别说我记性差。`,`好，${v}。开场介绍这一关过了。`,`${v}，名字收到，人也看见了。`]]);
  if(key==='favoriteFood')return role(id,[
   [`喜欢${v}呀，那下次选吃的可以少纠结一个选项。`,`好嘛，${v}这一票先给你记着。`,`原来是${v}，你一说，我也有点馋。`,`${v}呀，感觉聊着聊着就要饿了。`,`收到，${v}。以后可别又在菜单面前说随便。`,`记住啦，喜欢${v}。这句比随便吃什么都好用。`,`好，${v}，先加入你的点菜单。`],
   [`${v}，记着啦。小事也值得记一下。`,`原来喜欢${v}，这下又知道你一点。`,`好，${v}。下次点菜不用猜你想吃什么了。`,`${v}呀，我还以为你会先说随便。`,`嗯，${v}，等聊到吃的就能用上了。`,`喜欢${v}，那就照自己的口味来。`,`记下${v}这一票了，改口味的时候再告诉我。`],
   [`${v}。好，菜单终于有个具体答案了。`,`收到，${v}。这个比随便好点多了。`,`行，${v}，你的菜单定位成功。`,`喜欢${v}啊，记住了，省得下次让我猜。`,`${v}这票算你的，不给你投丢。`,`好，${v}。你终于给了菜单一个明确方向。`,`记着呢，${v}。下次说随便，我可就翻这条了。`]]);
  return role(id,[[`好，${v}。这件小事我记着。`,`说好啦，${v}，以后聊到就有话接了。`],[`嗯，${v}，不用说得很大声，我会记着。`,`好，${v}，慢慢把这件事安排明白。`],[`行，${v}。别光说，记得自己也留意一下。`,`收到，${v}，这下有个明确安排了。`]]);
 }
 function recall(id,intent,f){
  const key={recallName:'name',recallFood:'favoriteFood',recallTravel:'travelPlace',recallAgreement:'agreement'}[intent];
  if(intent==='recallAll'){
   const parts=[f.name?'你叫'+f.name:'',f.favoriteFood?'喜欢吃'+f.favoriteFood:''].filter(Boolean).join('，');
   if(parts)return role(id,[[`记得呀，${parts}。怎么，来抽查我啦？`,`${parts}。这次不用重新介绍啦。`],[`${parts}，我没忘。小事也会记着的。`,`记得，${parts}。你还担心我记串呀？`],[`${parts}。行不行，记性还可以吧。`,`记得，${parts}。抽查通过。`]]);
  }
  const v=f[key];if(!v)return role(id,[['这条你还没告诉我呀，我可不能临时编一个。','我这里没留着这个，想说的话可以再告诉我。'],['这件事我还不知道呢，不想替你猜。','这条没留着，要不你再告诉我一次？'],['这条不知道，不能现场编答案。','我这儿没记着，别让我蒙。']]);
  const item=key==='name'?'你叫'+v:key==='favoriteFood'?'你喜欢吃'+v:key==='travelPlace'?'你想去'+v:'说好'+v;
  return role(id,[[`记得呀，${item}。刚才那句话我有认真听。`,`${item}，对不对？别小看我的记性。`,`当然记着，${item}。这是在抽查我吗？`],[`${item}，没忘。你说过的小事，我会留意。`,`记得，${item}。不用每回都重新说啦。`,`${item}嘛，猜都不用猜。`],[`${item}。记性还行，下一题。`,`记得，${item}。这回不需要提示。`,`${item}，标准答案还没变吧？`]]);
 }
 function flow(id,t,m){
  if(!m.lastTopic)return null;
  if(/^(?:那你呢|你呢|你选|你来选)[？?。！!]*$/.test(t)&&['food','stateFood','bored','treat'].includes(m.lastTopic))return {intent:'food',pool:role(id,[['我选热乎的。你刚说的那口味，也可以一起算上。','我先选吃的，再出去走走。这个顺序没意见吧？'],['我想先吃点热乎的，再慢慢走一会儿。','我选聊得舒服的那个，吃什么可以慢慢挑。'],['先吃饭。饿着做选择，菜单容易看成论文。','我选吃完再散步，一次解决两道选择题。']])};
  if(/^都(?:想)?要[！!。～~]*$/.test(t)&&['bored','food','treat'].includes(m.lastTopic))return {intent:'food',pool:role(id,[['好嘛，那就先散步再吃，给你排上了。','行，你负责都要，我负责把顺序理好。'],['那就一样一样来，不用非得二选一。','也行，先走一会儿，再找想吃的，别赶。'],['都要是吧，行，先吃再走。别把菜单也打包了。','可以，吃饭和散步排个队，不会打架。']])};
  if(/^(?:谁啊|谁呀|是谁|谁呢)[？?。]*$/.test(t)&&['missing','tease','compliment'].includes(m.lastTopic))return {intent:'tease',pool:role(id,[['就你呀，还想让我点名两遍。','你自己对号入座得这么快，还装不知道。'],['谁刚刚在这儿说话，就说谁呀。','你不是已经猜到了，还要我再说一遍呀。'],['就你。聊天框里目前没第三个人。','谁先接话就是谁，这题不难。']])};
  if(/^(?:真的|真的吗|真的假的|是吗)[？?。！!]*$/.test(t)&&['compliment','missing','tease'].includes(m.lastTopic))return {intent:m.lastTopic,pool:role(id,[['真的呀，刚夸完你就开始质检啦。','这次没逗你，别把好话听成陷阱嘛。'],['嗯，这句是认真说的，你不用反复确认。','你先收着，别让我夸完又解释一遍。'],['真的，不附赠第二份质检报告。','这句不用打假，放心收着。']])};
  if(/^(?:好(?:的|呀|啊|吧)?|嗯+|行|可以)[。！!～~]*$/.test(t)&&['sleep','study','work','tired'].includes(m.lastTopic))return {intent:m.lastTopic,pool:role(id,[['那就先去做你的事，不用特地等我再回一句。','好，说到做到哦，别又拿起手机。'],['嗯，先按自己的节奏来，不急着回我。','好，那就先去歇着，或者把手头那点做完。'],['行，批准你先去忙自己的。','好，别一边答应一边继续刷。']])};
  return null;
 }
